import React, { useState } from 'react';
import { Link } from 'react-router-dom';

type Faculty = {
  id: string;
  name: string;
  email: string;
  department: string;
  position: string;
};

export default function FacultySection() {
  const [faculty, setFaculty] = useState<Faculty[]>([]);
  const [formData, setFormData] = useState<Omit<Faculty, 'id'>>({ 
    name: '', 
    email: '', 
    department: '',
    position: ''
  });

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const newFaculty = {
      ...formData,
      id: Date.now().toString()
    };
    setFaculty([...faculty, newFaculty]);
    setFormData({ name: '', email: '', department: '', position: '' });
  };

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value } = e.target;
    setFormData({
      ...formData,
      [name]: value
    });
  };

  return (
    <div className="faculty-container">
      <h1>Faculty Management</h1>
      <Link to="/">Back to Home</Link>
      
      <form onSubmit={handleSubmit}>
        <input
          type="text"
          name="name"
          placeholder="Faculty Name"
          value={formData.name}
          onChange={handleChange}
          required
        />
        <input
          type="email"
          name="email"
          placeholder="Email"
          value={formData.email}
          onChange={handleChange}
          required
        />
        <input
          type="text"
          name="department"
          placeholder="Department"
          value={formData.department}
          onChange={handleChange}
          required
        />
        <input
          type="text"
          name="position"
          placeholder="Position"
          value={formData.position}
          onChange={handleChange}
          required
        />
        <button type="submit">Add Faculty</button>
      </form>

      <div className="faculty-list">
        <h2>Faculty Records</h2>
        {faculty.length > 0 ? (
          <ul>
            {faculty.map(faculty => (
              <li key={faculty.id}>
                <p>Name: {faculty.name}</p>
                <p>Email: {faculty.email}</p>
                <p>Department: {faculty.department}</p>
                <p>Position: {faculty.position}</p>
              </li>
            ))}
          </ul>
        ) : (
          <p>No faculty added yet</p>
        )}
      </div>
    </div>
  );
}
